def _parse(self, text: str, expected_parameters: tuple[str, ...]) -> GeneratedDocumentation:
    raw = self._json_text(text)
    try:
        value = json.loads(raw)
    except json.JSONDecodeError:
        raise DocumentationError("invalid_output", "Model output is not valid JSON") from None
    if not isinstance(value, dict) or set(value) != _OUTPUT_FIELDS:
        raise DocumentationError("invalid_output", "Model output fields do not match the documentation schema")

    summary = self._required_text(value["summary"], "summary")
    details = self._required_text(value["detailed_description"], "detailed_description")
    parameters = self._parameters(value["parameters"], expected_parameters)
    return_value = self._optional_text(value["return_value"], "return_value")
    lists = {field: self._string_list(value[field], field) for field in _LIST_FIELDS}
    return GeneratedDocumentation(
        summary=summary,
        detailed_description=details,
        parameters=parameters,
        return_value=return_value,
        raises=lists["raises"],
        side_effects=lists["side_effects"],
        dependencies=lists["dependencies"],
        notes=lists["notes"],
    )

def build(self, retrieval_result: RetrievalResult, max_chars: int) -> RAGContext:
    """Build context blocks within a source-code character budget."""
    if max_chars < 1:
        raise ContextBuildError("max_chars must be positive")

    blocks: list[ContextBlock] = []
    used_chars = 0
    omitted_count = 0
    for chunk in self._unique_sorted(retrieval_result.results):
        code_chars = len(chunk.code)
        if used_chars + code_chars > max_chars:
            omitted_count += 1
            continue
        blocks.append(self._block(chunk))
        used_chars += code_chars

    return RAGContext(blocks=tuple(blocks), total_chars=used_chars, omitted_count=omitted_count)

def post_json(
    base_url: str,
    endpoint: str,
    payload: dict[str, Any],
    *,
    api_key: str | None,
    timeout_seconds: float,
) -> dict[str, Any]:
    """POST JSON and return an object while keeping headers and response bodies out of errors."""
    headers = {"Content-Type": "application/json"}
    if api_key:
        headers["Authorization"] = f"Bearer {api_key}"
    request = urllib.request.Request(
        f"{base_url}/{endpoint.lstrip('/')}",
        data=json.dumps(payload).encode("utf-8"),
        headers=headers,
        method="POST",
    )
    try:
        with urllib.request.urlopen(request, timeout=timeout_seconds) as response:
            raw = response.read()
    except urllib.error.HTTPError as error:
        raise OpenAICompatibleHTTPError(
            "HTTPError", f"OpenAI-compatible request failed with HTTP {error.code}"
        ) from None
    except (socket.timeout, TimeoutError):
        raise OpenAICompatibleHTTPError("TimeoutError", "OpenAI-compatible request timed out") from None
    except urllib.error.URLError as error:
        if isinstance(error.reason, (socket.timeout, TimeoutError)):
            raise OpenAICompatibleHTTPError("TimeoutError", "OpenAI-compatible request timed out") from None
        raise OpenAICompatibleHTTPError("ConnectionError", "OpenAI-compatible request failed") from None
    except OSError:
        raise OpenAICompatibleHTTPError("ConnectionError", "OpenAI-compatible request failed") from None
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        raise OpenAICompatibleHTTPError(
            "invalid_response_encoding", "OpenAI-compatible response was not valid UTF-8"
        ) from None
    try:
        decoded = json.loads(text)
    except json.JSONDecodeError:
        raise OpenAICompatibleHTTPError(
            "invalid_response_json", "OpenAI-compatible response was not valid JSON"
        ) from None
    if not isinstance(decoded, dict):
        raise OpenAICompatibleHTTPError(
            "invalid_response_top_level", "OpenAI-compatible response must be a JSON object"
        )
    return decoded

