def create_app(settings: APISettings | None = None) -> FastAPI:
    """Create the local API without making external provider calls."""
    error_responses = {
        status: {"model": ErrorEnvelope, "description": "Safe CodeCompass error"}
        for status in (400, 404, 409, 422, 500, 502, 503, 504)
    }
    app = FastAPI(title="CodeCompass API", version="1.0.0", responses=error_responses)
    app.state.runtime = APIRuntime(settings or APISettings.from_environment())

    @app.exception_handler(APIError)
    def api_error(_: Request, error: APIError) -> JSONResponse:
        return _error(error.status, error.code, error.message, error.details)

    @app.exception_handler(RequestValidationError)
    def validation_error(_: Request, error: RequestValidationError) -> JSONResponse:
        fields = [
            {"location": [str(part) for part in item.get("loc", ())], "type": str(item.get("type", "invalid")), "message": "Invalid request value"}
            for item in error.errors()
        ]
        return _error(422, "validation_error", "Request validation failed", {"fields": fields})

    @app.exception_handler(DocumentationError)
    def documentation_error(_: Request, error: DocumentationError) -> JSONResponse:
        status = {"invalid_request": 422, "not_found": 404, "ambiguous": 409, "insufficient_evidence": 422, "provider_timeout": 504}.get(error.code, 502)
        details = {"candidates": [asdict(item) for item in error.candidates]} if error.candidates else {}
        if error.provider_error_type:
            details["provider_error_type"] = error.provider_error_type
        return _error(status, f"documentation_{error.code}", error.message, details)

    @app.exception_handler(QAError)
    def qa_error(_: Request, error: QAError) -> JSONResponse:
        status = 422 if error.stage == "request" else 502 if error.stage == "llm" else 500
        return _error(status, f"qa_{error.stage}_failed", "Grounded answer generation failed")

    @app.exception_handler(RetrievalError)
    def retrieval_error(_: Request, error: RetrievalError) -> JSONResponse:
        if error.stage == "embedding_configuration_mismatch":
            return _error(409, "embedding_configuration_mismatch", "Embedding configuration does not match the index; re-index is required")
        if error.stage == "vector_index_state_invalid":
            return _error(409, "vector_index_state_invalid", "Vector index state is invalid; re-index storage is required")
        status = 422 if error.stage == "query" else 502 if error.stage == "embedding" else 500
        return _error(status, f"retrieval_{error.stage}_failed", "Retrieval failed")

    @app.exception_handler(VectorIndexStateError)
    def vector_index_state_error(_: Request, __: VectorIndexStateError) -> JSONResponse:
        return _error(409, "vector_index_state_invalid", "Vector index state is invalid; re-index storage is required")

    @app.exception_handler(EvaluationArtifactError)
    def evaluation_error(_: Request, __: EvaluationArtifactError) -> JSONResponse:
        return _error(503, "evaluation_unavailable", "Evaluation artifact is unavailable")

    @app.exception_handler(ValueError)
    def configuration_error(_: Request, __: ValueError) -> JSONResponse:
        return _error(422, "provider_configuration_invalid", "Provider configuration is invalid")

    @app.exception_handler(StorageError)
    def storage_error(_: Request, __: StorageError) -> JSONResponse:
        return _error(500, "storage_failure", "Metadata storage failed")

    @app.exception_handler(Exception)
    def unexpected_error(_: Request, __: Exception) -> JSONResponse:
        return _error(500, "internal_error", "An internal error occurred")

    @app.get("/health", response_model=HealthResponse)
    def health(runtime: APIRuntime = Depends(get_runtime)) -> HealthResponse:
        runtime.store.initialize()
        return HealthResponse()

    @app.get("/projects", response_model=list[ProjectResponse])
    def projects(runtime: APIRuntime = Depends(get_runtime)) -> list[ProjectResponse]:
        return [_project(item) for item in runtime.store.list_projects()]

    @app.get("/projects/{project_id}", response_model=ProjectResponse)
    def project(project_id: int, runtime: APIRuntime = Depends(get_runtime)) -> ProjectResponse:
        item = runtime.require_project(project_id)
        files = runtime.store.list_source_files(project_id)
        symbols = tuple(symbol for source in files for symbol in runtime.store.list_symbols(source.id))
        chunks = runtime.store.list_chunks(project_id)
        generation_matches = runtime.vector_generation_matches(item)
        vectors = runtime.collection(project_id).list_ids() if generation_matches else ()
        return ProjectResponse(
            **_project(item).model_dump(exclude={"files", "symbols", "chunks", "vector_complete"}),
            files=len(files),
            symbols=len(symbols),
            chunks=len(chunks),
            vector_complete=(
                generation_matches
                and set(vectors) == {chunk.chunk_id for chunk in chunks}
            ),
        )

    @app.post("/projects/index", response_model=IndexProjectResponse)
    def index_project(body: IndexProjectRequest, runtime: APIRuntime = Depends(get_runtime)) -> dict[str, Any]:
        return runtime.index(body.repository_path, body.project_name, body.embedding)

    @app.post("/projects/index-jobs", response_model=IndexJobResponse, status_code=202)
    def start_index_job(body: IndexJobRequest, runtime: APIRuntime = Depends(get_runtime)) -> IndexJobResponse:
        return _index_job(
            runtime.start_index_job(
                repository_path=body.repository_path,
                project_id=body.project_id,
                project_name=body.project_name,
                override=body.embedding,
            )
        )

    @app.get("/projects/index-jobs/active", response_model=IndexJobResponse)
    def active_index_job(runtime: APIRuntime = Depends(get_runtime)) -> IndexJobResponse | Response:
        job = runtime.active_indexing_job()
        return _index_job(job) if job is not None else Response(status_code=204)

    @app.get("/projects/index-jobs/{job_id}", response_model=IndexJobResponse)
    def index_job(job_id: str, runtime: APIRuntime = Depends(get_runtime)) -> IndexJobResponse:
        return _index_job(runtime.indexing_job(job_id))

    @app.get("/projects/{project_id}/files", response_model=list[SourceFileResponse])
    def files(project_id: int, runtime: APIRuntime = Depends(get_runtime)) -> list[SourceFileResponse]:
        runtime.require_project(project_id)
        return [SourceFileResponse(id=item.id, relative_path=item.relative_path, size_bytes=item.size_bytes, sha256=item.sha256, status=item.status) for item in runtime.store.list_source_files(project_id)]

    @app.get("/projects/{project_id}/files/{file_id}/content", response_model=SourceContentResponse)
    def file_content(project_id: int, file_id: int, runtime: APIRuntime = Depends(get_runtime)) -> dict[str, Any]:
        return runtime.source_content(project_id, file_id)

    @app.get("/projects/{project_id}/symbols", response_model=list[SymbolResponse])
    def symbols(project_id: int, file_id: int | None = Query(default=None, ge=1), runtime: APIRuntime = Depends(get_runtime)) -> list[SymbolResponse]:
        runtime.require_project(project_id)
        files = runtime.store.list_source_files(project_id)
        if file_id is not None:
            files = tuple(item for item in files if item.id == file_id)
            if not files:
                raise APIError(404, "file_not_found", "Source file was not found")
        return [
            SymbolResponse(id=item.id, file_id=item.file_id, kind=item.kind, name=item.name, qualified_name=item.qualified_name, is_async=item.is_async, start_line=item.start_line, end_line=item.end_line, parameters=list(item.parameters), returns=item.returns)
            for source in files for item in runtime.store.list_symbols(source.id)
        ]

    @app.post("/projects/{project_id}/search", response_model=SearchResponse)
    def search(project_id: int, body: SearchRequest, runtime: APIRuntime = Depends(get_runtime)) -> SearchResponse:
        config = runtime.embedding_config(body.embedding)
        service = runtime.retrieval(project_id, config, compatible=body.method != "lexical")
        result = getattr(service, f"search_{body.method}")(RetrievalQuery(body.query, project_id, body.limit))
        chunks = runtime.citation_chunks(project_id, tuple(item.chunk_id for item in result.results))
        return SearchResponse(
            query=body.query,
            method=body.method,
            results=[
                RetrievedChunkResponse(
                    **_citation(chunks[item.chunk_id]).model_dump(),
                    score=item.score,
                    code=chunks[item.chunk_id].code,
                    retrieval_method=item.retrieval_method,
                )
                for item in result.results
            ],
        )

    @app.post("/projects/{project_id}/ask", response_model=AskResponse)
    def ask(project_id: int, body: AskRequest, runtime: APIRuntime = Depends(get_runtime)) -> AskResponse:
        retrieval = runtime.retrieval(project_id, runtime.embedding_config(body.embedding), compatible=body.method != "lexical")
        service = GroundedQAService(retrieval, RAGContextBuilder(), QAPromptBuilder(), create_llm(runtime, body.llm))
        answer = service.answer(QARequest(question=body.question, project_id=project_id, retrieval_method=body.method, max_tokens=body.max_tokens))
        chunks = runtime.citation_chunks(project_id, tuple(item.chunk_id for item in answer.citations))
        return AskResponse(question=answer.question, answer=answer.answer, method=answer.retrieval_method, citations=[_citation(chunks[item.chunk_id]) for item in answer.citations], omitted_context_count=answer.omitted_context_count, llm_model=answer.llm_model, llm_provider=answer.llm_provider, finish_reason=answer.finish_reason)

    @app.post("/projects/{project_id}/documentation", response_model=DocumentationResponse)
    def documentation(project_id: int, body: DocumentationRequest, runtime: APIRuntime = Depends(get_runtime)) -> dict[str, Any]:
        runtime.require_project(project_id)
        result = FunctionDocumentationService(runtime.store, create_llm(runtime, body.llm)).document_symbol(project_id, body.identifier, language=body.language, max_tokens=body.max_tokens)
        response = asdict(result)
        chunks = runtime.citation_chunks(project_id, tuple(item.chunk_id for item in result.citations))
        project_name = runtime.require_project(project_id).name
        response["citations"] = [
            _documentation_citation(chunks[item.chunk_id], project_name)
            for item in result.citations
        ]
        target = chunks[result.extracted.citation.chunk_id]
        response["extracted"]["citation"] = _documentation_citation(target, project_name)
        return response

    @app.get("/evaluation/summary", response_model=EvaluationResponse)
    def evaluation_summary(runtime: APIRuntime = Depends(get_runtime)) -> EvaluationResponse:
        digest, data = runtime.evaluation(performance=False)
        return EvaluationResponse(artifact_sha256=digest, data=data)

    @app.get("/evaluation/performance", response_model=EvaluationResponse)
    def evaluation_performance(runtime: APIRuntime = Depends(get_runtime)) -> EvaluationResponse:
        digest, data = runtime.evaluation(performance=True)
        return EvaluationResponse(artifact_sha256=digest, data=data)

    return app

def run_diagnosis(
    states: Sequence[IndexState],
    official_baseline_directory: Path,
    work_directory: Path,
    *,
    ollama_url: str = "http://127.0.0.1:11434",
) -> dict[str, Any]:
    """Compare full rebuilds and same-input Chroma replicas without running E1-E5."""
    if {state.label for state in states} != {"official_baseline", "performance", "failed_fresh"}:
        raise BaselineReproducibilityError("diagnosis requires official_baseline, performance, and failed_fresh states")
    if work_directory.exists() and any(work_directory.iterdir()):
        raise BaselineReproducibilityError("replica work directory must be empty")
    work_directory.mkdir(parents=True, exist_ok=True)

    import chromadb

    provider = OllamaEmbeddingProvider(model=MODEL, base_url=ollama_url, timeout_seconds=180.0, truncate=False)
    model_metadata = baseline._ollama_metadata(ollama_url, MODEL)
    if model_metadata.get("model_digest") != MODEL_DIGEST:
        raise BaselineReproducibilityError("embedding model digest differs from Official Baseline")

    frozen_artifact = _read_json(Path("data/evaluation/results/official_baseline_v1.json"))
    performance_artifact = _read_json(Path("data/evaluation/results/scalability_performance_v1.json"))
    frozen_run = next(
        item
        for item in frozen_artifact["query_runs"]
        if item["question_id"] == QUERY_ID and item["method"] == "semantic"
    )
    frozen_ids = [item["chunk_id"] for item in frozen_run["predictions"]]

    query_calls = [provider.embed_text(QUERY_TEXT).vector for _ in range(5)]
    query_vector = query_calls[0]
    query_determinism = _vector_call_determinism(query_calls)

    state_payloads: list[dict[str, Any]] = []
    state_vectors: dict[str, dict[str, list[float]]] = {}
    state_chunks: dict[str, tuple[StoredChunk, ...]] = {}
    state_metadatas: dict[str, dict[str, dict[str, Any]]] = {}
    for state in sorted(states, key=lambda item: item.label):
        chunks = SQLiteMetadataStore(state.root / "metadata.sqlite3").list_chunks(1)
        client = chromadb.PersistentClient(path=str(state.root / "chroma"))
        collection = client.get_collection(state.collection_name)
        raw = collection.get(include=["embeddings", "metadatas"])
        vectors = {
            str(chunk_id): [float(value) for value in vector]
            for chunk_id, vector in zip(raw["ids"], raw["embeddings"], strict=True)
        }
        metadatas = {
            str(chunk_id): dict(metadata)
            for chunk_id, metadata in zip(raw["ids"], raw["metadatas"], strict=True)
        }
        rankings = [_query_collection(collection, query_vector, TOP_K) for _ in range(3)]
        state_vectors[state.label] = vectors
        state_chunks[state.label] = chunks
        state_metadatas[state.label] = metadatas
        state_payloads.append(
            {
                "state_id": state.label,
                "provenance": state.provenance,
                "repository_commit": REPOSITORY_COMMIT,
                "chunk_count": len(chunks),
                "vector_count": len(vectors),
                "collection_name": state.collection_name,
                "collection_configuration": dict(collection.metadata or {}),
                "corpus_snapshot_sha256": _corpus_hash(chunks),
                "insertion_order_sha256": _insertion_order_hash(chunks),
                "insertion_order_chunk_ids": [chunk.chunk_id for chunk in chunks],
                "stored_vector_set_sha256": _vector_set_hash(vectors),
                "within_index_repeats_identical": rankings[0] == rankings[1] == rankings[2],
                "ordered_results": rankings[0],
                "matches_frozen_top_10_ids": [item["chunk_id"] for item in rankings[0][:10]] == frozen_ids,
            }
        )

    corpus_hashes = {item["corpus_snapshot_sha256"] for item in state_payloads}
    order_hashes = {item["insertion_order_sha256"] for item in state_payloads}
    vector_hashes = {item["stored_vector_set_sha256"] for item in state_payloads}
    if len(corpus_hashes) != 1 or len(order_hashes) != 1 or len(vector_hashes) != 1:
        raise BaselineReproducibilityError("upstream corpus or stored vectors differ across full-pipeline states")

    reference_vectors = state_vectors["official_baseline"]
    reference_chunks = {item.chunk_id: item for item in state_chunks["official_baseline"]}
    affected = []
    exact_scores = {chunk_id: _cosine(query_vector, vector) for chunk_id, vector in reference_vectors.items()}
    exact_order = sorted(exact_scores, key=lambda chunk_id: (-exact_scores[chunk_id], chunk_id))
    for chunk_id in AFFECTED_CHUNK_IDS:
        chunk = reference_chunks[chunk_id]
        embedding_calls = [provider.embed_text(chunk.embedding_text).vector for _ in range(3)]
        stored_vectors = {label: vectors[chunk_id] for label, vectors in state_vectors.items()}
        affected.append(
            {
                "chunk_id": chunk_id,
                "relative_path": chunk.relative_path,
                "qualified_name": chunk.qualified_name,
                "start_line": chunk.start_line,
                "end_line": chunk.end_line,
                "direct_exact_rank": exact_order.index(chunk_id) + 1,
                "direct_cosine_similarity": exact_scores[chunk_id],
                "direct_cosine_distance": 1.0 - exact_scores[chunk_id],
                "embedding_calls": _vector_call_determinism(embedding_calls),
                "stored_float32_sha256_by_state": {
                    label: _float_hash(vector, "f") for label, vector in sorted(stored_vectors.items())
                },
                "stored_vectors_identical_across_states": len({_float_hash(vector, "f") for vector in stored_vectors.values()}) == 1,
                "provider_vs_stored_max_abs_difference": max(
                    abs(left - right)
                    for left, right in zip(embedding_calls[0], stored_vectors["official_baseline"], strict=True)
                ),
            }
        )

    reference_chunks_order = state_chunks["official_baseline"]
    reference_metadata = state_metadatas["official_baseline"]
    replica_results = []
    for replica in range(1, REPLICA_COUNT + 1):
        path = work_directory / f"replica-{replica}"
        collection = chromadb.PersistentClient(path=str(path)).get_or_create_collection(
            name=f"diagnosis_replica_{replica}", metadata={"hnsw:space": "cosine"}
        )
        ordered_ids = [chunk.chunk_id for chunk in reference_chunks_order]
        collection.upsert(
            ids=ordered_ids,
            embeddings=[reference_vectors[chunk_id] for chunk_id in ordered_ids],
            metadatas=[reference_metadata[chunk_id] for chunk_id in ordered_ids],
        )
        repeats = [_query_collection(collection, query_vector, TOP_K) for _ in range(3)]
        replica_results.append(
            {
                "replica_id": f"same_input_replica_{replica}",
                "collection_configuration": dict(collection.metadata or {}),
                "corpus_snapshot_sha256": next(iter(corpus_hashes)),
                "insertion_order_sha256": next(iter(order_hashes)),
                "stored_vector_set_sha256": next(iter(vector_hashes)),
                "within_index_repeats_identical": repeats[0] == repeats[1] == repeats[2],
                "ordered_results": repeats[0],
                "matches_frozen_top_10_ids": [item["chunk_id"] for item in repeats[0][:10]] == frozen_ids,
            }
        )

    replica_top_ids = {tuple(item["chunk_id"] for item in replica["ordered_results"][:10]) for replica in replica_results}
    full_state_top_ids = {tuple(item["chunk_id"] for item in state["ordered_results"][:10]) for state in state_payloads}
    provenance = _baseline_provenance(official_baseline_directory, frozen_artifact, performance_artifact)
    payload = {
        "schema_version": 1,
        "diagnosis_version": "baseline_reproducibility_diagnosis_v1",
        "complete": True,
        "scope": {
            "query_id": QUERY_ID,
            "method": "semantic",
            "repository": "pallets/flask",
            "repository_commit": REPOSITORY_COMMIT,
            "top_k": TOP_K,
            "full_pipeline_states": len(states),
            "same_input_vector_index_replicas": REPLICA_COUNT,
            "experiment_matrix_executed": False,
        },
        "manifest": {
            "protocol_sha256": portable_sha256(Path("data/evaluation/retrieval_improvement_protocol_v1.json")),
            "frozen_input_sha256": {
                "benchmark": portable_sha256(Path("data/evaluation/bilingual_benchmark_v1.json")),
                "official_baseline": portable_sha256(Path("data/evaluation/results/official_baseline_v1.json")),
                "performance": portable_sha256(Path("data/evaluation/results/scalability_performance_v1.json")),
                "error_analysis": portable_sha256(Path("data/evaluation/results/retrieval_error_analysis_v1.json")),
                "error_annotations": portable_sha256(Path("data/evaluation/retrieval_error_annotations_v1.json")),
            },
            "embedding_model": MODEL,
            "embedding_model_digest": MODEL_DIGEST,
            "ollama_version": model_metadata.get("version"),
            "chromadb_version": chromadb.__version__,
            "python": platform.python_version(),
            "system": platform.system(),
            "collection_configuration": {"hnsw:space": "cosine"},
            "retrieval_parameters": {"method": "semantic", "limit": TOP_K},
        },
        "frozen_ordered_top_10_chunk_ids": frozen_ids,
        "query_embedding_determinism": query_determinism,
        "chunk_corpus_determinism": {
            "all_corpus_snapshots_identical": len(corpus_hashes) == 1,
            "all_insertion_orders_identical": len(order_hashes) == 1,
            "corpus_snapshot_sha256": next(iter(corpus_hashes)),
            "insertion_order_sha256": next(iter(order_hashes)),
        },
        "stored_embedding_determinism": {
            "all_vector_sets_identical": len(vector_hashes) == 1,
            "stored_vector_set_sha256": next(iter(vector_hashes)),
            "affected_chunks": affected,
        },
        "direct_exact_similarity": {
            "implementation": "stdlib float64 cosine over stored float32 vectors; deterministic chunk_id secondary order",
            "affected_score_gaps": [
                {
                    "higher_chunk_id": left,
                    "lower_chunk_id": right,
                    "cosine_similarity_gap": exact_scores[left] - exact_scores[right],
                }
                for left, right in zip(AFFECTED_CHUNK_IDS, AFFECTED_CHUNK_IDS[1:])
            ],
            "affected_candidates": [
                {
                    "chunk_id": item["chunk_id"],
                    "exact_rank": item["direct_exact_rank"],
                    "cosine_similarity": item["direct_cosine_similarity"],
                    "cosine_distance": item["direct_cosine_distance"],
                }
                for item in affected
            ],
        },
        "full_pipeline_states": state_payloads,
        "same_input_vector_index_replicas": replica_results,
        "original_baseline_provenance": provenance,
        "findings": {
            "within_index_query_order_stable": all(item["within_index_repeats_identical"] for item in [*state_payloads, *replica_results]),
            "full_pipeline_top_10_order_varies": len(full_state_top_ids) > 1,
            "same_input_replica_top_10_order_varies": len(replica_top_ids) > 1,
            "affected_candidates_are_exact_ties": len({exact_scores[item] for item in AFFECTED_CHUNK_IDS}) != len(AFFECTED_CHUNK_IDS),
            "narrowest_supported_diagnosis": "Rebuild-dependent behavior is isolated to Chroma vector-index construction/search state; the specific internal mechanism is not proven.",
            "specific_hnsw_cause_claimed": False,
        },
        "strategy_assessment": {
            "deterministic_rebuild": {
                "status": "not_established",
                "reason": "Identical corpus, insertion order, vectors, configuration, and query produced more than one Top-10 ordering across fresh replicas."
            },
            "frozen_baseline_index": {
                "status": "recommended_pending_snapshot_freeze",
                "reason": "The surviving Official Baseline index reproduces the frozen ordered IDs and would hold index state constant across ablations.",
                "requirements": [
                    "freeze and hash all three SQLite/Chroma index states",
                    "verify collection identity and exact baseline reproduction for all 180 query-method records",
                    "use read-only copies for every experiment run",
                ],
            },
            "exact_evaluation_harness": {
                "status": "scientifically_valid_separate_harness_not_production_equivalent",
                "reason": "Exact cosine is deterministic but changes ANN retrieval semantics and would require a separately versioned evaluation baseline.",
            },
            "tolerance_based_comparison": {
                "status": "rejected_for_current_protocol",
                "reason": "The exact ordered-ID gate remains unchanged.",
            },
        },
    }
    baseline._validate_portable_payload(payload, tuple(state.root for state in states) + (official_baseline_directory, work_directory))
    return payload

def _incremental_base(self, project: ProjectRecord) -> _IncrementalBase | None:
    if project.index_schema_version != INDEX_SCHEMA_VERSION or project.vector_generation is None:
        return None
    vector_index = self.collection_factory(project.id)
    try:
        generation = vector_index.active_generation()
        metadata = dict(vector_index.get_index_metadata())
    except VectorIndexError as error:
        raise self._state_error(error) from error
    if generation != project.vector_generation:
        raise self._state_error(VectorIndexStateError("SQLite and Chroma generations do not match"))
    if metadata.get("codecompass:index_schema_version") != INDEX_SCHEMA_VERSION:
        raise self._state_error(VectorIndexStateError("SQLite and Chroma index schemas do not match"))
    dimensions = metadata.get("codecompass:embedding_dimensions")
    if not isinstance(dimensions, int) or dimensions < 0:
        raise self._state_error(VectorIndexStateError("Active embedding dimensions are invalid"))
    stored_identity = (
        metadata.get("codecompass:embedding_provider"),
        metadata.get("codecompass:embedding_endpoint_sha256"),
        metadata.get("codecompass:embedding_model"),
    )
    requested_identity = (
        self.embedding_identity.provider,
        self.embedding_identity.endpoint_sha256,
        self.embedding_identity.model,
    )
    if stored_identity != requested_identity:
        return None
    chunks = self.store.list_chunks(project.id)
    expected_ids = tuple(sorted(chunk.chunk_id for chunk in chunks))
    if expected_ids and dimensions < 1:
        raise self._state_error(VectorIndexStateError("Active embedding dimensions are invalid"))
    if not expected_ids and dimensions != 0:
        raise self._state_error(VectorIndexStateError("Empty vector index dimensions are invalid"))
    if (
        expected_ids
        and self.embedding_identity.dimensions is not None
        and self.embedding_identity.dimensions != dimensions
    ):
        return None
    try:
        vector_ids = vector_index.list_ids()
    except VectorIndexError as error:
        raise self._state_error(error) from error
    if vector_ids != expected_ids:
        return None
    return _IncrementalBase(
        project,
        vector_index,
        chunks,
        generation,
        dimensions,
        {key: value for key, value in metadata.items() if isinstance(value, (str, int))},
    )

def create_app(settings: APISettings | None = None) -> FastAPI:
    """Create the local API without making external provider calls."""
    error_responses = {
        status: {"model": ErrorEnvelope, "description": "Safe CodeCompass error"}
        for status in (400, 404, 409, 422, 500, 502, 503, 504)
    }
    app = FastAPI(title="CodeCompass API", version="1.0.0", responses=error_responses)
    app.state.runtime = APIRuntime(settings or APISettings.from_environment())

    @app.exception_handler(APIError)
    def api_error(_: Request, error: APIError) -> JSONResponse:
        return _error(error.status, error.code, error.message, error.details)

    @app.exception_handler(RequestValidationError)
    def validation_error(_: Request, error: RequestValidationError) -> JSONResponse:
        fields = [
            {"location": [str(part) for part in item.get("loc", ())], "type": str(item.get("type", "invalid")), "message": "Invalid request value"}
            for item in error.errors()
        ]
        return _error(422, "validation_error", "Request validation failed", {"fields": fields})

    @app.exception_handler(DocumentationError)
    def documentation_error(_: Request, error: DocumentationError) -> JSONResponse:
        status = {"invalid_request": 422, "not_found": 404, "ambiguous": 409, "insufficient_evidence": 422, "provider_timeout": 504}.get(error.code, 502)
        details = {"candidates": [asdict(item) for item in error.candidates]} if error.candidates else {}
        if error.provider_error_type:
            details["provider_error_type"] = error.provider_error_type
        return _error(status, f"documentation_{error.code}", error.message, details)

    @app.exception_handler(QAError)
    def qa_error(_: Request, error: QAError) -> JSONResponse:
        status = 422 if error.stage == "request" else 502 if error.stage == "llm" else 500
        return _error(status, f"qa_{error.stage}_failed", "Grounded answer generation failed")

    @app.exception_handler(RetrievalError)
    def retrieval_error(_: Request, error: RetrievalError) -> JSONResponse:
        if error.stage == "embedding_configuration_mismatch":
            return _error(409, "embedding_configuration_mismatch", "Embedding configuration does not match the index; re-index is required")
        if error.stage == "vector_index_state_invalid":
            return _error(409, "vector_index_state_invalid", "Vector index state is invalid; re-index storage is required")
        status = 422 if error.stage == "query" else 502 if error.stage == "embedding" else 500
        return _error(status, f"retrieval_{error.stage}_failed", "Retrieval failed")

    @app.exception_handler(VectorIndexStateError)
    def vector_index_state_error(_: Request, __: VectorIndexStateError) -> JSONResponse:
        return _error(409, "vector_index_state_invalid", "Vector index state is invalid; re-index storage is required")

    @app.exception_handler(EvaluationArtifactError)
    def evaluation_error(_: Request, __: EvaluationArtifactError) -> JSONResponse:
        return _error(503, "evaluation_unavailable", "Evaluation artifact is unavailable")

    @app.exception_handler(ValueError)
    def configuration_error(_: Request, __: ValueError) -> JSONResponse:
        return _error(422, "provider_configuration_invalid", "Provider configuration is invalid")

    @app.exception_handler(StorageError)
    def storage_error(_: Request, __: StorageError) -> JSONResponse:
        return _error(500, "storage_failure", "Metadata storage failed")

    @app.exception_handler(Exception)
    def unexpected_error(_: Request, __: Exception) -> JSONResponse:
        return _error(500, "internal_error", "An internal error occurred")

    @app.get("/health", response_model=HealthResponse)
    def health(runtime: APIRuntime = Depends(get_runtime)) -> HealthResponse:
        runtime.store.initialize()
        return HealthResponse()

    @app.get("/projects", response_model=list[ProjectResponse])
    def projects(runtime: APIRuntime = Depends(get_runtime)) -> list[ProjectResponse]:
        return [_project(item) for item in runtime.store.list_projects()]

    @app.get("/projects/{project_id}", response_model=ProjectResponse)
    def project(project_id: int, runtime: APIRuntime = Depends(get_runtime)) -> ProjectResponse:
        item = runtime.require_project(project_id)
        files = runtime.store.list_source_files(project_id)
        symbols = tuple(symbol for source in files for symbol in runtime.store.list_symbols(source.id))
