    except VectorIndexError:
        return False

def _failed_stage(self, code: str, details: dict[str, Any]) -> str:
    if code.startswith("embedding_"):
        return "preflight"
    errors = details.get("errors")
    if isinstance(errors, list) and errors and isinstance(errors[0], dict):
        stage = errors[0].get("stage")
        mapped = {
            "scan": "scanning",
            "parse": "parsing",
            "chunk": "chunking",
            "embedding": "embedding",
            "vector": "verifying",
            "storage": "activating",
        }.get(stage)
        if mapped is not None:
            return mapped
    if code == "indexing_failed":
        return "scanning"
    if code == "repository_changed_during_index":
        return "verifying"
    if code in {"vector_indexing_failed", "vector_index_state_invalid"}:
        return "verifying"
    return "failed"

def citation_chunks(self, project_id: int, chunk_ids: tuple[str, ...]) -> dict[str, StoredChunk]:
    """Hydrate API navigation metadata from canonical SQLite rows."""
    self.require_project(project_id)
    requested = tuple(dict.fromkeys(chunk_ids))
    chunks = {
        chunk.chunk_id: chunk
        for chunk in self.store.get_chunks_by_chunk_ids(project_id, requested)
    }
    files = {source.id: source for source in self.store.list_source_files(project_id)}
    if set(chunks) != set(requested) or any(
        chunk.file_id not in files or files[chunk.file_id].relative_path != chunk.relative_path
        for chunk in chunks.values()
    ):
        raise APIError(500, "citation_metadata_missing", "Trusted citation metadata is unavailable")
    return chunks

def _assertion_hint(self, source_code: str, language: DocumentationLanguage) -> tuple[str, ...]:
    try:
        tree = ast.parse(textwrap.dedent(source_code))
    except SyntaxError:
        return ()
    assertion = next((node for node in ast.walk(tree) if isinstance(node, ast.Assert)), None)
    if assertion is None:
        return ()
    expression = assertion.test
    if (
        isinstance(expression, ast.Compare)
        and len(expression.ops) == 1
        and isinstance(expression.ops[0], ast.Eq)
        and len(expression.comparators) == 1
    ):
        actual = ast.unparse(expression.left)
        expected = ast.unparse(expression.comparators[0])
        sentence = (
            f"این تست بررسی می‌کند که نتیجه {actual} با {expected} برابر باشد."
            if language == "fa"
            else f"This test verifies that {actual} equals {expected}."
        )
        return (f"Trusted AST assertion: {actual} == {expected}", f"Grounded summary: {sentence}")
    return (f"Trusted AST assertion: {ast.unparse(expression)}",)

