def _incremental_base(self, project: ProjectRecord) -> _IncrementalBase | None:
    if project.index_schema_version != INDEX_SCHEMA_VERSION or project.vector_generation is None:
        return None
    vector_index = self.collection_factory(project.id)
    try:
        generation = vector_index.active_generation()
        metadata = dict(vector_index.get_index_metadata())
    except VectorIndexError as error:
        raise self._state_error(error) from error
    if generation != project.vector_generation:
        raise self._state_error(VectorIndexStateError("SQLite and Chroma generations do not match"))
    if metadata.get("codecompass:index_schema_version") != INDEX_SCHEMA_VERSION:
        raise self._state_error(VectorIndexStateError("SQLite and Chroma index schemas do not match"))
    dimensions = metadata.get("codecompass:embedding_dimensions")
    if not isinstance(dimensions, int) or dimensions < 0:
        raise self._state_error(VectorIndexStateError("Active embedding dimensions are invalid"))
    stored_identity = (
        metadata.get("codecompass:embedding_provider"),
        metadata.get("codecompass:embedding_endpoint_sha256"),
        metadata.get("codecompass:embedding_model"),
    )
    requested_identity = (
        self.embedding_identity.provider,
        self.embedding_identity.endpoint_sha256,
        self.embedding_identity.model,
    )
    if stored_identity != requested_identity:
        return None
    chunks = self.store.list_chunks(project.id)
    expected_ids = tuple(sorted(chunk.chunk_id for chunk in chunks))
    if expected_ids and dimensions < 1:
        raise self._state_error(VectorIndexStateError("Active embedding dimensions are invalid"))
    if not expected_ids and dimensions != 0:
        raise self._state_error(VectorIndexStateError("Empty vector index dimensions are invalid"))
    if (
        expected_ids
        and self.embedding_identity.dimensions is not None
        and self.embedding_identity.dimensions != dimensions
    ):
        return None
    try:
        vector_ids = vector_index.list_ids()
    except VectorIndexError as error:
        raise self._state_error(error) from error
    if vector_ids != expected_ids:
        return None
    return _IncrementalBase(
        project,
        vector_index,
        chunks,
        generation,
        dimensions,
        {key: value for key, value in metadata.items() if isinstance(value, (str, int))},
    )

def index_project(self, project_id: int) -> VectorIndexingResult:
    """Replace one project's vectors and verify exact chunk-id equality."""
    if self.vector_index is None:
        raise ValueError("Vector index is required for project activation")
    if self.store.get_project(project_id) is None:
        raise ValueError(f"Unknown project id: {project_id}")
    chunks = self.store.list_chunks(project_id)
    sqlite_ids = tuple(sorted(chunk.chunk_id for chunk in chunks))
    prepared = self.prepare_chunks(chunks)
    embedded = list(prepared.embedded)
    truncated = list(prepared.truncated)
    errors = list(prepared.errors)

    if errors:
        vector_ids, vector_errors = self._current_ids(project_id)
        errors.extend(vector_errors)
        return self._result(project_id, sqlite_ids, vector_ids, embedded, truncated, errors)

    target_identity = prepared.identity
    records = prepared.records(project_id)
    vector_ids: tuple[str, ...] = ()
    try:
        replacement = bool(getattr(self.vector_index, "managed", False))
        if replacement:
            metadata = self.identity_metadata(target_identity) if target_identity is not None else {
                "codecompass:embedding_schema": 1,
                "codecompass:embedding_dimensions": 0,
            }
            self.vector_index.replace_collection(records, metadata, sqlite_ids)
        else:
            existing = set(self.vector_index.list_ids(project_id))
            self.vector_index.upsert(records)
            stale = tuple(sorted(existing - set(sqlite_ids)))
            self.vector_index.delete(stale)
        vector_ids = self.vector_index.list_ids(project_id)
    except VectorIndexError as error:
        errors.append(VectorIndexingError("vector", (), type(error).__name__, str(error)))
        vector_ids, list_errors = self._current_ids(project_id)
        errors.extend(list_errors)

    if not errors and set(vector_ids) != set(sqlite_ids):
        difference = tuple(sorted(set(vector_ids) ^ set(sqlite_ids)))
        errors.append(
            VectorIndexingError(
                "vector",
                difference,
                "IncompleteIndex",
                "SQLite and vector-index chunk ids do not match",
            )
        )
    if not errors and target_identity is not None and not replacement:
        try:
            self.vector_index.set_index_metadata(self.identity_metadata(target_identity))
        except VectorIndexError as error:
            errors.append(VectorIndexingError("vector", (), type(error).__name__, str(error)))
    return self._result(project_id, sqlite_ids, vector_ids, embedded, truncated, errors)

def discard_empty_managed_index(self) -> None:
    """Remove an uncommitted managed index whose active generation is empty."""
    if not self.managed or self.active_pointer is None:
        raise VectorIndexStateError("Managed vector index is required")
    if self.list_ids():
        raise VectorIndexStateError("Non-empty active vector index cannot be discarded")
    for name in self._managed_collection_names():
        try:
            collection = self._client.get_collection(name=name)
            metadata = collection.metadata if isinstance(collection.metadata, dict) else {}
            if metadata.get(BINDING_LOGICAL) != self.collection_name:
                continue
            if self.project_id is not None and metadata.get(BINDING_PROJECT) != self.project_id:
                continue
        except Exception:
            continue
        self._delete_collection(name)
    self.active_pointer.unlink(missing_ok=True)
    self._collection = None
    self._active_name = None
    self._dimension = None

def vector_generation_matches(self, project: Any) -> bool:
