def validate_pinned_repository(repository: Path, expected_commit: str) -> str:
    """Require an exact Git commit and a clean tracked/untracked worktree."""
    commit = _git(repository, "rev-parse", "HEAD")
    if commit != expected_commit:
        raise RepositoryValidationError(
            f"repository commit mismatch: expected {expected_commit}, got {commit}"
        )
    if _git(repository, "status", "--porcelain", "--untracked-files=normal"):
        raise RepositoryValidationError("repository worktree must be clean before indexing")
    return commit

def find_nearest(self):
    sorted_days = self.sort_days()
    for i in range(len(sorted_days)):
        if sorted_days[i] in self.schedule:
            index = sorted_days[i]
            for time in range(len(self.schedule[index])):
                if self.schedule[index][time] is not None and self.schedule[index][time] != "Not Available":
                    return sorted_days[i], time + 1  # sorted_days[i] == day

def is_available(self, day, time):
    time = int(time) - 1
    if self.schedule[day]:
        if self.schedule[day][time] == "Available":
            return True
        else:
            return False

def set_schedule(self, day, queue):
    today = self.day_manager.get_curr_day()
    while not queue.is_empty():
        time = queue.dequeue()
        time = int(time) - 1
        if int(today) != int(day) and int(today) + 1 <= int(day) <= int(today) + 7 and 0 <= time <= 11:
            if day not in self.schedule:
                self.schedule[day] = Array(12)
            self.schedule[day][time] = "Available"

def doctor_cancel_appointment(self, day, curr_user):
    doctor = self.get_doctor_obj(curr_user)
    if doctor:
        doctor.decrement_visits()
        doctor.schedule.cancel_appointment(day)
        ids = doctor.appointments.cancel_appointment(day)
        if ids:
            while not ids.is_empty():
                patient_id = ids.dequeue()
                patient = self.get_patient_obj(patient_id)
                time = patient.appointments.canceled_by_doctor(day, curr_user)
                patient.appointments.cancel_appointment(day, time)
            return True

def cancel_appointment(self, day):
    queue = Queue()
    if day in self.appointments:
        for time in range(len(self.appointments[day])):
            if self.appointments[day][int(time) - 1]:
                patient_id = self.appointments[day][int(time) - 1]
                queue.enqueue(patient_id)
                self.create_canceled(day, int(time) + 1, patient_id)
                self.appointments[day][int(time) - 1] = None
        return queue

def speciality_city(self, city, speciality):  # displays doctors by city and speciality
    array = DynamicArray()
    if city in self.table:
        if speciality in self.table[city]:
            if self.table[city][speciality]:
                sll = self.table[city][speciality]
                for node in sll:
                    if node.data in self.doctors:
                        array.append(self.doctors[node.data])
    return array

def rehashing(self, new_array):
    m = len(self.array)
    for item in self.array:
        if item and item != "deleted":
            for i in range(m):
                index = self.hash_function(item.key, i)
                if new_array[index] is None:
                    new_array[index] = item
                    break

    return new_array

